    std::uint64_t *aOUSaltC = pDomainSaltSet->mOrbiterUpdate.mSaltC;
    std::uint64_t *aOUSaltD = pDomainSaltSet->mOrbiterUpdate.mSaltD;
    std::uint64_t *aOUSaltE = pDomainSaltSet->mOrbiterUpdate.mSaltE;
    std::uint64_t *aOUSaltF = pDomainSaltSet->mOrbiterUpdate.mSaltF;
    std::uint64_t *aOUSaltG = pDomainSaltSet->mOrbiterUpdate.mSaltG;
