    // [kdf-a arx]
    const std::uint64_t aNonceWordA = TwistMix64::DiffuseC(pNonce * 0xE0A8D16FA97F7C29ULL + 0xE5EBD7F2B55365B4ULL);
    const std::uint64_t aNonceWordB = TwistMix64::DiffuseC(pNonce * 0xFAD592FDD306337DULL + 0x99AC288481B1CE4AULL);
    const std::uint64_t aNonceWordC = TwistMix64::DiffuseC(pNonce * 0xC0AE1C2D94E7800FULL + 0xF3AE18C0A0DDAE6BULL);
    const std::uint64_t aNonceWordD = TwistMix64::DiffuseA(pNonce * 0xBCB4B5CE351D4EADULL + 0xE13783B34C98314FULL);
    const std::uint64_t aNonceWordE = TwistMix64::DiffuseB(pNonce * 0xB29B32B7D1127935ULL + 0xC0DAC704C2D7B6DDULL);
