    const std::uint64_t aNonceWordJ = TwistMix64::DiffuseA(pNonce * 0xF11D194D14A39C77ULL + 0xB11BE6EA73EDA055ULL);
    const std::uint64_t aNonceWordK = TwistMix64::DiffuseA(pNonce * 0x833B2252F2EA26FBULL + 0xC75A4019E0D96E8AULL);
    const std::uint64_t aNonceWordL = TwistMix64::DiffuseA(pNonce * 0xBEB6818DD2EAED8FULL + 0xF8251562CA4D43B5ULL);
    const std::uint64_t aNonceWordM = TwistMix64::DiffuseC(pNonce * 0xE70FAC468894FC6BULL + 0xA9220582CA3195D6ULL);
    const std::uint64_t aNonceWordN = TwistMix64::DiffuseB(pNonce * 0xA4C6A0884AAE7655ULL + 0x9EDBB0DFA2D987FFULL);
