            aOrbiterA = (((aWandererC + RotL64(aIngress, 6U)) + 0x17EE2C1783591162ULL) + aOASaltF[((aIndex + 381U)) & S_SALT1]) + aNonceWordK;
            aOrbiterF = (aWandererB + RotL64(aScatter, 47U)) + 0xA3B90EBC21CD7550ULL;
            aOrbiterJ = ((aWandererD + RotL64(aPrevious, 11U)) + RotL64(aCarry, 39U)) + 0x87202C82E77F1C28ULL;
            //
            aOrbiterG = (aOrbiterG + aOrbiterC) + 0x18179F8E790F68CAULL;
